import math
def priority(task, state, m=5.0, k=0.5, b=0.5, hard=1e6, prem_guard=2.0, conv_cap=3.0, conv_due=0.15):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - est - state.now
    if task.tenant == 'premium':
        if slack < 0:
            return hard + task.weight / est
        if slack < prem_guard * est:
            return hard * 0.1 + m * task.weight / est
        return m * task.weight / est * math.exp(-slack / (k * mean_est)) * (1.0 + b * wait / est)
    # standard: WSPT with capped aging and a small due nudge for near-due jobs
    age = 1.0 + b * min(wait / est, conv_cap)
    base = task.weight / est * age
    if task.due > 0 and slack > 0:
        base *= 1.0 + conv_due * math.exp(-slack / (k * mean_est))
    return base  # tuned (m=3.71,k=0.175,b=0.144,hard=3.84e+05,prem_guard=1.52,conv_cap=8.04,conv_due=0.0852)

import math
def priority(task, state, m=4.0, k=0.6, b=1.5, qlo=2.0, qhi=6.0, eps=0.3):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    wait = now - task.release
    slack = max(0.0, task.due - est - now)
    mean = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    urgency = tier * task.weight / est * math.exp(-slack / (k * mean))
    q = state.queue_len
    pressure = 0.0
    if q > qlo:
        pressure = min(1.0, (q - qlo) / max(qhi - qlo, 1e-6))
    aging = 1.0 + (b * (1.0 + pressure)) * (wait / est)
    if task.tenant == 'premium' and now >= task.due:
        return 1e6 + urgency * aging
    if task.tenant == 'standard':
        return urgency * aging / (est ** eps)
    return urgency * aging  # tuned (m=4.56,k=2.34,b=4.3,qlo=2.4,qhi=1.72,eps=0.724)

def priority(task, state, premium_boost=1e5, lateness_mult=4.0, k=1.0, age=0.5, spt_pow=1.0, share_weight=0.5):
    slack = task.due - state.now - task.estimated_runtime
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    if task.tenant == 'premium':
        if slack < 0:
            return 1e7 + (-slack) * lateness_mult / est
        urgency = math.exp(-max(slack, 0.0) / (k * mean_est))
        return premium_boost * urgency + task.weight / (est ** spt_pow)
    if slack < 0:
        return 1e6 + wait / est
    ratio = wait / est
    mem_frac = task.resource_need / max(state.free, 1e-6)
    base = (task.weight / (est ** spt_pow)) * (1 + age * ratio)
    return base / (1.0 + share_weight * mem_frac)  # tuned (premium_boost=7.35e+04,lateness_mult=3.4,k=0.524,age=0.557,spt_pow=0.941,share_weight=0.746)

def priority(task, state, k=0.5, m=4.0, alpha=1.0, beta=1.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    if task.tenant == 'premium':
        # SRTF-like urgency scaled by weight, plus overdue escalation
        urgency = task.weight / max(slack + task.estimated_runtime, 1e-6)
        overdue = max(0.0, state.now - task.due)
        return atc + alpha * urgency + beta * overdue / max(task.estimated_runtime, 1e-6)
    # standard: penalize large memory footprint to reduce head-of-line blocking
    mem_penalty = 1.0 + task.resource_need / max(state.capacity, 1e-6)
    return atc / mem_penalty  # tuned (k=0.133,m=2.06,alpha=2.89,beta=1.88)

