    return -task.due + b * ratio + 1.0 / max(task.estimated_runtime, 1e-6)

def priority(task, state, premium_boost=5.0, aging=2.0, late_mult=20.0, slack_k=3.0, spt_pow=1.0):
    import math
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    slack = task.due - state.now - est
    spt_term = 1.0 / (est ** spt_pow)
    if task.tenant == 'premium':
        if slack < 0:
            return late_mult * premium_boost * spt_term + wait
        return premium_boost * task.weight / est * math.exp(-max(0.0, slack) / (slack_k * max(state.mean_est, 1e-6))) * (1.0 + aging * wait / est)
    return spt_term * (1.0 + aging * wait / est)  # tuned (premium_boost=1.78,aging=0.685,late_mult=21.4,slack_k=2.95,spt_pow=1.11)

def priority(task, state, m=5.0, k=0.7, b=1.0, horizon=2.0, prem_slack_scale=0.5):
    import math
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    mean_est = max(state.mean_est, 1e-6)
    congestion = state.queue_work / max(state.capacity * horizon, 1e-6)
    if task.tenant == 'premium':
        slack = task.due - est - state.now
        # premium uses tighter slack scale and congestion-aware urgency
        urg = m * task.weight / est * math.exp(-max(0.0, slack) / (prem_slack_scale * k * mean_est))
        if slack < 0:
            urg *= (1.0 + (-slack) / mean_est)
        aging = 1.0 + b * wait / est
        return urg * aging * (1.0 + congestion)
    else:
        slack = max(0.0, task.due - est - state.now)
        atc = task.weight / est * math.exp(-slack / (k * mean_est))
        aging = 1.0 + b * wait / est
        return atc * aging * (1.0 + congestion)  # tuned (m=19.3,k=0.266,b=0.468,horizon=1.81,prem_slack_scale=0.528)

def priority(task, state, m=3.0, b=0.5, k=2.0, late_mult=4.0, prem_boost=1.0, p=2.0, mem_bias=1.0):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    slack = task.due - est - state.now
    atc = task.weight / est * math.exp(-max(0.0, slack) / (k * max(state.mean_est, 1e-6)))
    aging = task.weight / est * (1 + b * wait / est)
    if aging > 0 and atc > 0:
        combined = aging ** (1.0 / p) * atc ** (1.0 - 1.0 / p)
    else:
        combined = aging + atc
    if slack < 0:
        combined *= late_mult * (1.0 - slack / est)
    if task.tenant == 'premium':
        combined *= prem_boost
    mem_ratio = task.resource_need / max(state.capacity, 1e-6)
    combined *= math.exp(-mem_bias * mem_ratio)
    return tier * combined  # tuned (m=6.16,b=1.63,k=2.63,late_mult=3.91,prem_boost=0.304,p=1.54,mem_bias=1.08)

def priority(task, state, m=6.0, k=0.5, age=1.5, guard=0.25):
    # Queue-aware: under load, emphasize premium SLO guard and aging; else SPT-ish.
    load = state.queue_work / max(state.capacity, 1e-6)
    wait = state.now - task.release
    slack = task.due - task.estimated_runtime - state.now
    tier = m if task.tenant == 'premium' else 1.0
    if load > guard:
        # overloaded: protect premium due dates, age standard requests
        if task.tenant == 'premium':
            return tier * (1e6 - max(task.due, state.now + task.estimated_runtime)) + age * wait
        return task.weight / max(task.estimated_runtime, 1e-6) * (1.0 + age * wait / max(task.estimated_runtime, 1e-6))
    else:
        # light load: ATC-like with modest tiering
        s = max(0.0, slack)
        return tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-s / (k * max(state.mean_est, 1e-6)))  # tuned (m=10.8,k=1.88,age=0.815,guard=0.15)

def priority(task, state, m=2.5, b=2.0, g=1.5, t=1.0, e=0.5):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    # Core aging WSPT
    base = tier * task.weight / est * (1.0 + b * wait / est)
    # Premium: hard lateness penalty grows without bound; standard: gentle slack urgency
    if task.tenant == 'premium':
        slack = task.due - state.now - est
        if slack < 0:
            late = -slack
            base *= (1.0 + g * late / est) * (1.0 + t * late / max(state.mean_est, 1e-6))
        else:
            base *= 1.0 + g * max(0.0, (est - slack)) / est
    else:
        # Standard: short-job bias to control p90 tail, scaled by queue load
        load = state.queue_work / max(state.capacity, 1e-6)
        base /= (est ** (e * (1.0 + load)))
    return base  # tuned (m=2.09,b=5.47,g=0.915,t=3.17,e=0.185)

