    return task.weight / est * (1.0 + w * ratio * ratio) + 1.0 / est  # tuned (m=3.97,k=0.984,c=2.07,w=3.81)

import math
def priority(task, state, m=5.0, k=1.0, c=1.5, b=1.0, lat_boost=2.0, prem_urg=0.7, std_urg=0.25):
    spt = 1.0 / max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    slack = task.due - task.estimated_runtime - state.now
    wait = state.now - task.release
    ratio = wait / max(task.estimated_runtime, 1e-6)
    if slack < 0:
        return 1e6 + lat_boost * tier * (-slack)
    urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    aging = 1.0 + b * ratio
    guard = 1e5 if ratio >= c else 0.0
    if task.tenant == 'premium':
        score = tier * spt * (prem_urg * urgency + (1.0 - prem_urg)) * aging
    else:
        score = tier * spt * (std_urg * urgency + (1.0 - std_urg)) * aging
    return guard + score  # tuned (m=2.56,k=3.94,c=0.975,b=1.41,lat_boost=4.4,prem_urg=0.798,std_urg=0.413)

def priority(task, state, m=5.5, b=2.5, k=1.5, guard=2.0, p90=2.5, tail=2.0, conv_tail=3.0):
    import math
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    aging = 1.0 + b * wait / est
    atc = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    base = tier * task.weight / est * aging * atc
    if task.tenant == 'premium':
        if slack < guard * est:
            base += 1e6 * (1.0 + (guard * est - slack) / est)
    else:
        tail_thresh = p90 * max(state.mean_est, 1e-6)
        if wait > tail_thresh:
            if task.task_type == 'conv':
                base *= 1.0 + conv_tail * (wait - tail_thresh) / est
            else:
                base *= 1.0 + tail * (wait - tail_thresh) / est
    return base  # tuned (m=7.51,b=5.09,k=0.656,guard=0.678,p90=1.66,tail=1.86,conv_tail=0.778)
